<?php
namespace App\Services;
use App\Models\PayrollRun; use App\Support\Money; use Brick\Math\BigDecimal;
class PayrollComparisonService
{
public function previousRegular(PayrollRun $run):?PayrollRun{$date=sprintf('%04d-%02d-01',$run->year,$run->month);$previous=\Carbon\Carbon::parse($date)->subMonth();return PayrollRun::where('run_type','regular')->where('year',$previous->year)->where('month',$previous->month)->whereIn('status',['approved','completed'])->orderByDesc('sequence')->first();}
public function compare(PayrollRun $current,?PayrollRun $previous=null):array{$previous?:=$this->previousRegular($current);$current->loadMissing('payslips.employee');if($previous)$previous->loadMissing('payslips.employee');$cur=$current->payslips->keyBy('employee_id');$prev=$previous?->payslips?->keyBy('employee_id')??collect();$ids=$cur->keys()->merge($prev->keys())->unique()->sort()->values();$rows=[];foreach($ids as $id){$c=$cur->get($id);$p=$prev->get($id);$employee=$c?->employee?:$p?->employee;$rows[]=['employee_id'=>$id,'employee_name'=>$employee?->name,'state'=>$c&&$p?'continuing':($c?'entered':'missing'),'current_net'=>$c?(string)$c->net_salary:'0.000','previous_net'=>$p?(string)$p->net_salary:'0.000','net_delta'=>Money::round(Money::d($c?(string)$c->net_salary:'0')->minus($p?(string)$p->net_salary:'0')),'current_gross'=>$c?(string)$c->gross_salary:'0.000','previous_gross'=>$p?(string)$p->gross_salary:'0.000','gross_delta'=>Money::round(Money::d($c?(string)$c->gross_salary:'0')->minus($p?(string)$p->gross_salary:'0')),'current_ssc'=>$c?(string)$c->ssc_employee:'0.000','previous_ssc'=>$p?(string)$p->ssc_employee:'0.000','current_tax'=>$c?(string)$c->income_tax:'0.000','previous_tax'=>$p?(string)$p->income_tax:'0.000'];}$fields=['gross_salary','net_salary','ssc_employee','ssc_employer','income_tax','surcharge'];$totals=[];foreach($fields as $field){$c=BigDecimal::zero();foreach($cur as $x)$c=$c->plus(Money::d((string)$x->{$field}));$p=BigDecimal::zero();foreach($prev as $x)$p=$p->plus(Money::d((string)$x->{$field}));$totals[$field]=['current'=>Money::round($c),'previous'=>Money::round($p),'delta'=>Money::round($c->minus($p))];}return['current'=>['id'=>$current->id,'month'=>$current->month,'year'=>$current->year],'previous'=>$previous?['id'=>$previous->id,'month'=>$previous->month,'year'=>$previous->year]:null,'totals'=>$totals,'employees'=>$rows];}
}
